Method.Implementation:
	#dim jmsgateway As EnsLib.JavaGateway.JavaGateway
	set jmsgateway = ""
	set topicConnection = ""
	set topicSubscriber = ""

	Set tStat = $$$OK

	$$$TRACE("JMSinboundAdapter OnTask for " _ ..BusinessHost.%ConfigName _ " in " _$NAMESPACE)

	 SET localhost=$SYSTEM.INetInfo.LocalHostName()            /* get host name */
     $$$TRACE("local host name is " _ localhost)
     set subNm = $Replace(localhost, ".co.ihc.com", "") _ "_" _ $NAMESPACE _ "_" _ ..BusinessHost.%ConfigName

	// get an instance of JMSGateway and connect to JMSGateway Super Server
	try {
		Set jmsgateway=##class(EnsLib.JavaGateway.JavaGateway).%New()
		Set classPath=##class(%ListOfDataTypes).%New()
		$$$TRACE("To connect: " _ ..JavaGateWayHost _ ":" _ ..JavaGateWayPort)

		Do classPath.Insert(..JMSJarPath)
		$$$TRACE("JMS Call Path added: " _ ..JMSJarPath)
		/*
		For n=1:1:$L(..JMSJarPath,":") {
			set jarFile = $P(..JMSJarPath,":",n)
            Do classPath.Insert(jarFile)
            $$$TRACE("JMS Call Path added: " _ jarFile)
        }
        */

		Set tStat=jmsgateway.%Connect(..JavaGateWayHost,..JavaGateWayPort,$NAMESPACE,5,classPath) 
		If 'tStat 
		{
			set tStat = $$$ISERR(status)
			set exp = ##class(%Exception.General).%New()
			set exp.Code = status.Name
			set exp.Data = status.Data
			set exp.Name = "Java Gateway connection error"
			Throw exp  
		}
		$$$TRACE("Connected to Java Gateway")
		// Set tcf=$classmethod(..JmsContainerClass,"%New",jmsgateway, ..JMSHost, ..JMSPort)
		set tcf = ##class(com.seebeyond.jms.client.STCTopicConnectionFactory).%New(jmsgateway, ..JMSHost, ..JMSPort)
	    set topicConnection = tcf.createTopicConnection()
	    do topicConnection.stop()
	    $$$TRACE("Connected to JMS Queue: " _ tcf)
	    $$$TRACE("Connected to JMS: " _ ..JMSHost _ ":" _ ..JMSPort)

	    set topicSession = topicConnection.createTopicSession(1, 1) // "true","Session.AUTO_ACKNOWLEDGE")

        set topic = topicSession.createTopic(..TopicName)
        $$$TRACE("Created sub: " _ ..TopicName)

        set topicSubscriber = topicSession.createDurableSubscriber(topic, subNm)
        $$$TRACE("createSubscriber")
        do topicConnection.start()
        $$$TRACE("receive with timeout")
    	set message=topicSubscriber.receive(5000)
        do {


    		if message = ""
    		{
	    		 $$$TRACE("No message in the queue")
	    		 Quit 
    		}
   			elseif message.%IsA("javax.jms.TextMessage")
			{
	   			$$$TRACE("Got a TextMessage: " _ message.getText())
	   			Set tStat = ..SendMessageToService(message.getText())	   
			}
			elseif message.%IsA("javax.jms.BytesMessage")
			{
				set arrLen = 10000
				set comMsg = ""
				$$$TRACE("Got a BytesMessage of length ")
				Set readStream=##class(%GlobalBinaryStream).%New()
        		// reserve a number of bytes since we are passing the stream by reference      
        		For i=1:1:arrLen Do readStream.Write("0")

        		do {            
		    		set bytesRead = message.readBytes(.readStream, arrLen)
		    		set msgText = readStream.Read(bytesRead)
		    		set comMsg = comMsg _ msgText
		  		 	$$$TRACE( "byte msg. length " _ bytesRead )
        		} while (bytesRead = arrLen)
		  		$$$TRACE("SendMessageToService: " _ $LENGTH(comMsg))
		  		try
		  		{
		  		Set tStat = ..SendMessageToService(comMsg)
		  		} 
		  		catch exp
		  		{
			  		$$$LOGERROR("ERROR in SendMessageToService " _ exp.Data)
			  		throw exp
		  		}		
			}
			$$$TRACE("Commit and close")
			Do topicSession.commit()
			//Get next message
			$$$TRACE("receive with timeout")
    		set message=topicSubscriber.receive(10)
        } while message '= ""
		Do topicSubscriber.close()

	    Do topicConnection.stop()
	    Do topicConnection.close()
	    $$$TRACE("Disconnect")
		Do jmsgateway.%Disconnect() 
	 } catch err
     {
	     if $GET(%objlasterror) '= ""
	    {
	        set errMsg =  $System.Status.GetErrorText(%objlasterror)
	    }
	    else
	    {
		    set errMsg = "No obj"
	    }
	    $$$LOGALERT("Exception: Name: " _ err.Name _ " / Location:" _ err.Location _ " / Data: " _err.Data _ " / Details: " _ errMsg)
	    Set tSC=$$$ERROR($$$GeneralError, err.Name _ " / Location:" _ err.Location _ " / Data: " _err.Data _ " " _ errMsg)

	    if (topicConnection '= "")
	    {
	      Do topicConnection.stop()
	      Do topicConnection.close()
	    }

	    if (topicSubscriber '= "")
	    {
	       Do topicSubscriber.close()
	    }

	    if (jmsgateway '= "")
	    {
		  	    Do jmsgateway.%Disconnect()
	    }
    }

	Quit tStat
